using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Windows.Forms;using System.Runtime.Serialization.Json;
namespace Frociart.Tests{
 internal static class InsertionTests{
  static int checks;static BindingFlags flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static string folder;
  static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
  static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,flags).GetValue(o);}
  static void Call(object o,string name){o.GetType().GetMethod(name,flags,null,Type.EmptyTypes,null).Invoke(o,null);Pump();}
  static void Pump(){for(int i=0;i<8;i++)Application.DoEvents();}
  static string Bytes(Diagram d){using(var stream=new MemoryStream()){new DataContractJsonSerializer(typeof(Diagram)).WriteObject(stream,d);return Convert.ToBase64String(stream.ToArray());}}
  static FlowNode N(string id,NodeKind kind,float cx,float top){var n=new FlowNode{Id=id,Kind=kind,Text=id,X=0,Y=top};n.X=cx-FlowCanvas.GetNodeBounds(n).Width/2;return n;}
  static Diagram Fixture(NodeKind kind){var d=new Diagram{Title="Inserimento su freccia"};d.Nodes.AddRange(new[]{N("s",NodeKind.Start,340,20),N("b",NodeKind.Output,340,430),N("e",NodeKind.End,340,680),N("m",kind,850,180)});d.Edges.AddRange(new[]{new FlowEdge{Id="drop",From="s",To="b"},new FlowEdge{Id="tail",From="b",To="e"}});return d;}
  static Point Center(FlowCanvas c,FlowNode n){var r=FlowCanvas.GetNodeBounds(n);return Point.Round(c.WorldToClient(new PointF(r.Left+r.Width/2,r.Top+r.Height/2)));}
  static void Mouse(FlowCanvas c,string method,Point p){typeof(FlowCanvas).GetMethod(method,flags).Invoke(c,new object[]{new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0)});Pump();}
  static void Shot(FlowCanvas c,string name){using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,new Rectangle(Point.Empty,c.Size));b.Save(Path.Combine(folder,name+".png"));}}
  static IEnumerable<Control> Walk(Control c){yield return c;foreach(Control child in c.Controls)foreach(var item in Walk(child))yield return item;}
  static void DecisionDrop(MainForm main,string choice){var c=main.Canvas;Mouse(c,"OnMouseDown",Center(c,main.Document.Nodes.First(x=>x.Id=="m")));Mouse(c,"OnMouseMove",Drop(c,0));Exception problem=null;int ticks=0;using(var timer=new Timer{Interval=30}){timer.Tick+=delegate{var dialog=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x!=main&&x.Text.StartsWith("Inserisci la decisione"));if(dialog==null){if(++ticks>150){problem=new Exception("Decision dialog missing");timer.Stop();}return;}timer.Stop();try{Check(!c.IsPointerGestureActive,"Decision chooser releases pointer capture before opening");Check(main.Document.Edges[0].To=="b","Decision chooser does not guess a continuation");((Button)Walk(dialog).First(x=>x is Button&&(x.Text==choice||choice=="Annulla"&&x.Text=="Annulla inserimento"))).PerformClick();}catch(Exception ex){problem=ex;dialog.Close();}};timer.Start();Mouse(c,"OnMouseUp",Drop(c,0));if(problem!=null)throw problem;}}
  static Point Drop(FlowCanvas c,float offset){return Point.Round(c.WorldToClient(new PointF(340+offset/c.Zoom,280)));}
  static void BranchDrop(MainForm form){
   var d=Examples.Parity();d.Nodes.Add(N("m",NodeKind.Process,1050,250));form.SetDocument(d,null,false);form.Canvas.FitToView();form.Canvas.SnapToGrid=false;Pump();var c=form.Canvas;var edge=d.Edges.First(x=>x.From=="check"&&x.Branch=="true");string old=edge.To;var points=c.GetExportRoute(d.Nodes.First(x=>x.Id==edge.From),d.Nodes.First(x=>x.Id==edge.To),edge.Branch);int segment=1;double length=0;for(int i=1;i<points.Count;i++){double next=Math.Pow(points[i].X-points[i-1].X,2)+Math.Pow(points[i].Y-points[i-1].Y,2);if(next>length){length=next;segment=i;}}
   var world=new PointF((points[segment].X+points[segment-1].X)/2,(points[segment].Y+points[segment-1].Y)/2);var target=Point.Round(c.WorldToClient(world));Mouse(c,"OnMouseDown",Center(c,d.Nodes.Last()));Mouse(c,"OnMouseMove",target);Check(Field<bool>(c,"insertReady"),"A routed decision line offers the same insertion affordance");Mouse(c,"OnMouseUp",target);Check(edge.To=="m"&&edge.Branch=="true"&&d.Edges.Any(x=>x.From=="m"&&x.To==old)&&d.Edges.Any(x=>x.From=="check"&&x.Branch=="false"&&x.To=="odd"),"Insertion into a routed Sì line preserves the No branch and continues to its old target");
  }
  static void Model(){
   foreach(var kind in new[]{NodeKind.Input,NodeKind.Process,NodeKind.Output,NodeKind.Call}){
    var d=Fixture(kind);var edge=d.Edges[0];Check(FlowInsertion.Apply(d,"m","drop","next"),"Detached block can be inserted: "+kind);Check(edge.Id=="drop"&&edge.From=="s"&&edge.To=="m"&&d.Edges.Any(x=>x.From=="m"&&x.To=="b"&&x.Branch=="next"),"Splice preserves source edge identity and creates the actual continuation");
   }
   var move=Fixture(NodeKind.Process);move.Edges.Add(new FlowEdge{Id="old-in",From="b",To="m"});move.Edges.First(x=>x.Id=="tail").From="m";
   Check(FlowInsertion.Apply(move,"m","drop","next"),"An already connected linear block can be moved into another line");
   Check(move.Edges.First(x=>x.Id=="old-in").To=="e"&&move.Edges.First(x=>x.Id=="tail").To=="b","Old location is bypassed and the original outgoing edge is reused");
   foreach(var kind in new[]{NodeKind.Start,NodeKind.End}){var d=Fixture(kind);string before=Bytes(d);Check(!FlowInsertion.Apply(d,"m","drop","next")&&Bytes(d)==before,"Endpoint cannot silently cut the flow: "+kind);}
   var decision=Fixture(NodeKind.Decision);string original=Bytes(decision);Check(!FlowInsertion.Apply(decision,"m","drop",null)&&Bytes(decision)==original,"Decision insertion requires an explicit continuation branch");Check(FlowInsertion.Apply(decision,"m","drop","false")&&decision.Edges.Any(x=>x.From=="m"&&x.Branch=="false"&&x.To=="b")&&!decision.Edges.Any(x=>x.From=="m"&&x.Branch=="true"),"Decision uses the chosen No continuation and leaves Sì free");
   var bad=Fixture(NodeKind.Process);bad.Edges.Add(new FlowEdge{From="b",To="m"});string badBefore=Bytes(bad);Check(FlowInsertion.Reason(bad,"m","drop")!=null&&!FlowInsertion.Apply(bad,"m","drop","next")&&Bytes(bad)==badBefore,"Ambiguous detachment is rejected atomically");
   var branch=Fixture(NodeKind.Output);branch.Nodes.First(x=>x.Id=="s").Kind=NodeKind.Decision;branch.Nodes[0].TrueLabel="Accetta";branch.Nodes[0].TrueColor="#365CD9";branch.Edges[0].Branch="true";Check(FlowInsertion.Apply(branch,"m","drop","next")&&branch.Edges[0].Branch=="true"&&branch.Nodes[0].TrueLabel=="Accetta"&&branch.Nodes[0].TrueColor=="#365CD9","Insertion into a decision branch preserves meaning, labels and colors");
  }
  static void Reset(MainForm form,NodeKind kind){form.SetDocument(Fixture(kind),null,false);form.Canvas.SnapToGrid=false;form.Canvas.FitToView();Pump();}
  [STAThread]static int Main(){try{Application.EnableVisualStyles();Ui.SetDarkMode(true,false);UiMotion.SetEnabled(false);folder=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"insertion");Directory.CreateDirectory(folder);Model();
   using(var form=new MainForm(null,true)){form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-3000,-2500);form.Size=new Size(1420,1000);form.Show();form.EnterEditor();Pump();
    foreach(var kind in new[]{NodeKind.Input,NodeKind.Process,NodeKind.Output,NodeKind.Call}){
     Reset(form,kind);var c=form.Canvas;string original=Bytes(form.Document);var node=form.Document.Nodes.First(x=>x.Id=="m");Mouse(c,"OnMouseDown",Center(c,node));Mouse(c,"OnMouseMove",Drop(c,65));float far=Field<float>(c,"insertStrength");Check(!Field<bool>(c,"insertReady"),"Glow starts before the insertion threshold");Shot(c,"01-approach-"+kind);
     Mouse(c,"OnMouseMove",Drop(c,8));float near=Field<float>(c,"insertStrength");Check(near>far&&Field<bool>(c,"insertReady"),"Blue fade increases with proximity and exposes a valid drop");
     Check(form.Document.Edges[0].To=="b"&&Field<System.Collections.ICollection>(form,"undo").Count==0,"Preview changes no edges or undo history");Shot(c,"02-ready-"+kind);
     Mouse(c,"OnMouseUp",Drop(c,8));Check(form.Document.Edges[0].To=="m"&&form.Document.Edges.Any(x=>x.From=="m"&&x.To=="b"),"Actual mouse release inserts the dragged block: "+kind);Check(Field<System.Collections.ICollection>(form,"undo").Count==1,"Movement and splice create exactly one Undo");Shot(c,"03-inserted-"+kind);Call(form,"Undo");Check(Bytes(form.Document)==original,"One Undo restores original graph and coordinates");Call(form,"Redo");Check(form.Document.Edges[0].To=="m","Redo restores the insertion");
    }
    Reset(form,NodeKind.Process);var canvas=form.Canvas;string before=Bytes(form.Document);Mouse(canvas,"OnMouseDown",Center(canvas,form.Document.Nodes.First(x=>x.Id=="m")));Mouse(canvas,"OnMouseMove",Drop(canvas,0));typeof(FlowCanvas).GetMethod("OnKeyDown",flags).Invoke(canvas,new object[]{new KeyEventArgs(Keys.Escape)});Pump();Check(Bytes(form.Document)==before&&Field<System.Collections.ICollection>(form,"undo").Count==0&&!Field<bool>(canvas,"insertReady"),"Escape restores the exact pre-drag document and removes the glow");
    Reset(form,NodeKind.Process);before=Bytes(form.Document);canvas.ViewOnly=true;Mouse(canvas,"OnMouseDown",Center(canvas,form.Document.Nodes.First(x=>x.Id=="m")));Mouse(canvas,"OnMouseMove",Drop(canvas,0));Mouse(canvas,"OnMouseUp",Drop(canvas,0));Check(Bytes(form.Document)==before,"Read-only execution cannot move or insert blocks");canvas.ViewOnly=false;
    Reset(form,NodeKind.Decision);before=Bytes(form.Document);DecisionDrop(form,"No");Check(form.Document.Edges[0].To=="m"&&form.Document.Edges.Any(x=>x.From=="m"&&x.Branch=="false"&&x.To=="b")&&!form.Document.Edges.Any(x=>x.From=="m"&&x.Branch=="true"),"Native choice connects No and leaves Sì free");Check(Field<System.Collections.ICollection>(form,"undo").Count==1,"Decision drag and branch choice share one Undo");Call(form,"Undo");Check(Bytes(form.Document)==before,"Decision Undo restores the entire original diagram");
    Reset(form,NodeKind.Decision);DecisionDrop(form,"Annulla");Check(form.Document.Edges[0].To=="b"&&form.Document.Edges.Count==2,"Cancelling the branch choice preserves the original line");
    BranchDrop(form);var demo=Fixture(NodeKind.Input);demo.Nodes.First(x=>x.Id=="s").Text="Inizio";demo.Nodes.First(x=>x.Id=="m").Text="x";demo.Nodes.First(x=>x.Id=="b").Text="x";demo.Nodes.First(x=>x.Id=="e").Text="Fine";DiagramIO.Save(Path.Combine(folder,"Desktop_demo.frociart"),demo);form.SetDocument(Fixture(NodeKind.Process),null,false);form.Close();
   }Console.WriteLine("INSERTION_FINISHED checks="+checks+" errors=0; native mouse messages, graph preservation, gradients and history.");return 0;
  }catch(Exception ex){Console.WriteLine(ex);return 1;}}
 }
}
